#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Difficulty {
    Easy,
    Medium,
    Hard,
    Mixed,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum HandStrength {
    Weak,
    Balanced,
    Strong,
    Preserve,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum PhaseTag {
    RangedSiege,
    Block,
    AssignDamage,
    Attack,
}

impl PhaseTag {
    fn combat_phase(self) -> CombatPhase {
        match self {
            Self::RangedSiege => CombatPhase::RangedSiege,
            Self::Block => CombatPhase::Block,
            Self::AssignDamage => CombatPhase::AssignDamage,
            Self::Attack => CombatPhase::Attack,
        }
    }

    fn decision_phase_count(self) -> usize {
        match self {
            Self::RangedSiege => 4,
            Self::Block => 3,
            Self::AssignDamage => 2,
            Self::Attack => 1,
        }
    }
}

#[derive(Debug, Clone)]
struct FixtureSpec {
    name: &'static str,
    difficulty: Difficulty,
    hand_strength: HandStrength,
    phase: PhaseTag,
    enemies: &'static [&'static str],
    hand: &'static [&'static str],
    units: &'static [&'static str],
    crystals: [u8; 4],
    fortified: bool,
    source_depleted: bool,
    blocking_relevant: bool,
    card_preservation_relevant: bool,
}

#[derive(Debug)]
struct DiagnosticRecord {
    spec: FixtureSpec,
    oracle: CombatSearchResult,
    greedy: CombatSearchResult,
    oracle_elapsed: Duration,
    greedy_elapsed: Duration,
    first_action_match: bool,
    signed_error: f64,
    oracle_blocks: bool,
    greedy_blocks: bool,
    oracle_remaining_hand: Vec<String>,
    greedy_remaining_hand: Vec<String>,
    oracle_combat_remaining: usize,
    greedy_combat_remaining: usize,
}

fn fixture(
    name: &'static str,
    difficulty: Difficulty,
    hand_strength: HandStrength,
    phase: PhaseTag,
    enemies: &'static [&'static str],
    hand: &'static [&'static str],
) -> FixtureSpec {
    FixtureSpec {
        name,
        difficulty,
        hand_strength,
        phase,
        enemies,
        hand,
        units: &[],
        crystals: [0; 4],
        fortified: false,
        source_depleted: false,
        blocking_relevant: matches!(phase, PhaseTag::Block | PhaseTag::AssignDamage),
        card_preservation_relevant: hand_strength == HandStrength::Preserve,
    }
}

