fn add_units(state: &mut GameState, unit_ids: &[&str]) {
    for &unit_name in unit_ids {
        let definition = mk_data::units::get_unit(unit_name).expect("diagnostic unit must exist");
        let instance_id =
            UnitInstanceId::from(format!("diagnostic_unit_{}", state.next_instance_counter));
        state.next_instance_counter += 1;
        state.players[0].units.push(PlayerUnit {
            instance_id,
            unit_id: UnitId::from(unit_name),
            level: definition.level,
            state: UnitState::Ready,
            wounded: false,
            used_resistance_this_combat: false,
            used_ability_indices: Vec::new(),
            mana_token: None,
        });
    }
}

fn apply_action(state: &mut GameState, action: &LegalAction) {
    let epoch = state.action_epoch;
    apply_legal_action(state, &mut UndoStack::new(), 0, action, epoch)
        .expect("diagnostic fixture action must apply");
}

fn advance_to_phase(state: &mut GameState, target: CombatPhase) {
    while state
        .combat
        .as_ref()
        .is_some_and(|combat| combat.phase != target)
    {
        let phase = state.combat.as_ref().unwrap().phase;
        let actions = enumerate_legal_actions(state, 0);
        let action = if phase == CombatPhase::AssignDamage {
            actions
                .actions
                .iter()
                .find(|action| matches!(action, LegalAction::AssignDamageToHero { .. }))
                .or_else(|| {
                    actions
                        .actions
                        .iter()
                        .find(|action| matches!(action, LegalAction::EndCombatPhase))
                })
        } else {
            actions
                .actions
                .iter()
                .find(|action| matches!(action, LegalAction::EndCombatPhase))
        }
        .unwrap_or_else(|| panic!("cannot advance diagnostic fixture from {phase:?} to {target:?}"))
        .clone();
        apply_action(state, &action);
    }
}

fn build_state(spec: &FixtureSpec, seed: u32) -> GameState {
    let mut state = create_solo_game(seed, Hero::Arythea);
    state.round_phase = RoundPhase::PlayerTurns;
    state.players[0].hand = spec.hand.iter().map(|&card| CardId::from(card)).collect();
    state.players[0].crystals = Crystals {
        red: spec.crystals[0],
        blue: spec.crystals[1],
        green: spec.crystals[2],
        white: spec.crystals[3],
    };
    state.source.dice = vec![
        SourceDie {
            id: SourceDieId::from(SOURCE_DIE_RED),
            color: ManaColor::Red,
            is_depleted: spec.source_depleted,
            taken_by_player_id: None,
        },
        SourceDie {
            id: SourceDieId::from(SOURCE_DIE_BLUE),
            color: ManaColor::Blue,
            is_depleted: spec.source_depleted,
            taken_by_player_id: None,
        },
        SourceDie {
            id: SourceDieId::from(SOURCE_DIE_WHITE),
            color: ManaColor::White,
            is_depleted: spec.source_depleted,
            taken_by_player_id: None,
        },
    ];
    add_units(&mut state, spec.units);

    let tokens: Vec<EnemyTokenId> = spec
        .enemies
        .iter()
        .map(|&enemy| EnemyTokenId::from(enemy))
        .collect();
    execute_enter_combat(
        &mut state,
        0,
        &tokens,
        spec.fortified,
        None,
        Default::default(),
    )
    .expect("diagnostic fixture must enter combat");
    advance_to_phase(&mut state, spec.phase.combat_phase());
    state
}

fn replay(state: &GameState, actions: &[LegalAction]) -> GameState {
    let mut result = state.clone();
    for action in actions {
        apply_action(&mut result, action);
    }
    result
}

fn has_block_action(actions: &[LegalAction]) -> bool {
    actions.iter().any(|action| {
        matches!(
            action,
            LegalAction::DeclareBlock { .. }
                | LegalAction::PlayCardSideways {
                    sideways_as: SidewaysAs::Block,
                    ..
                }
        )
    })
}

fn combat_remaining(state: &GameState) -> usize {
    state
        .combat
        .as_ref()
        .map(|combat| {
            combat
                .enemies
                .iter()
                .filter(|enemy| !enemy.is_defeated)
                .count()
        })
        .unwrap_or(0)
}

fn remaining_hand(state: &GameState) -> Vec<String> {
    state.players[0]
        .hand
        .iter()
        .map(ToString::to_string)
        .collect()
}

fn mean(values: impl Iterator<Item = f64>) -> f64 {
    let values: Vec<f64> = values.collect();
    if values.is_empty() {
        return 0.0;
    }
    values.iter().sum::<f64>() / values.len() as f64
}

fn print_boolean_group(
    records: &[DiagnosticRecord],
    label: &str,
    predicate: impl Fn(&DiagnosticRecord) -> bool,
) {
    for selected in [true, false] {
        let group: Vec<&DiagnosticRecord> = records
            .iter()
            .filter(|record| predicate(record) == selected)
            .collect();
        println!(
            "BIAS\t{label}\t{selected}\tcount={}\tmean_signed={:.2}\tmean_abs={:.2}\tmatch_rate={:.3}",
            group.len(),
            mean(group.iter().map(|record| record.signed_error)),
            mean(group.iter().map(|record| record.signed_error.abs())),
            mean(group.iter().map(|record| f64::from(record.first_action_match))),
        );
    }
}

fn print_numeric_group(
    records: &[DiagnosticRecord],
    label: &str,
    key: impl Fn(&DiagnosticRecord) -> usize,
) {
    let mut groups: BTreeMap<usize, Vec<&DiagnosticRecord>> = BTreeMap::new();
    for record in records {
        groups.entry(key(record)).or_default().push(record);
    }
    for (value, group) in groups {
        println!(
            "GROUP\t{label}\t{value}\tcount={}\tmean_signed={:.2}\tmean_abs={:.2}\tmatch_rate={:.3}",
            group.len(),
            mean(group.iter().map(|record| record.signed_error)),
            mean(group.iter().map(|record| record.signed_error.abs())),
            mean(group.iter().map(|record| f64::from(record.first_action_match))),
        );
    }
}

fn print_category_group(
    records: &[DiagnosticRecord],
    label: &str,
    key: impl Fn(&DiagnosticRecord) -> String,
) {
    let mut groups: BTreeMap<String, Vec<&DiagnosticRecord>> = BTreeMap::new();
    for record in records {
        groups.entry(key(record)).or_default().push(record);
    }
    for (value, group) in groups {
        println!(
            "GROUP\t{label}\t{value}\tcount={}\tmean_signed={:.2}\tmean_abs={:.2}\tmatch_rate={:.3}",
            group.len(),
            mean(group.iter().map(|record| record.signed_error)),
            mean(group.iter().map(|record| record.signed_error.abs())),
            mean(group.iter().map(|record| f64::from(record.first_action_match))),
        );
    }
}

#[test]
#[ignore = "manual 40-fixture Oracle comparison"]
fn greedy_vs_oracle_broad_diagnostic() {
    let fixtures = representative_fixtures();
    assert_eq!(fixtures.len(), 40);
    let oracle_config = CombatSearchConfig {
        node_limit: 1_000_000,
        seed_rollouts: 500,
        ..CombatSearchConfig::default()
    };
    let greedy_config = GreedyCombatConfig::default();
    let mut records = Vec::with_capacity(fixtures.len());

    println!("fixture\tdifficulty\thand_strength\tphase\tenemies\thand_size\tdecision_phases\tblocking_tag\tpreservation_tag\toracle_blocks\tgreedy_blocks\tfirst_match\tsigned_error\toracle_score\tgreedy_score\toracle_fame\tgreedy_fame\toracle_wounds\tgreedy_wounds\toracle_cards\tgreedy_cards\toracle_complete\toracle_nodes\tgreedy_nodes\toracle_ms\tgreedy_ms\toracle_first\tgreedy_first");
    for (index, spec) in fixtures.into_iter().enumerate() {
        let state = build_state(&spec, 10_000 + index as u32);

        let started = Instant::now();
        let oracle = search_combat(&state, &oracle_config);
        let oracle_elapsed = started.elapsed();
        let started = Instant::now();
        let greedy = search_combat_greedy(&state, &greedy_config)
            .unwrap_or_else(|error| panic!("{}: greedy resolver failed: {error}", spec.name));
        let greedy_elapsed = started.elapsed();

        let oracle_state = replay(&state, &oracle.actions);
        let greedy_state = replay(&state, &greedy.actions);
        let first_action_match = oracle.actions.first() == greedy.actions.first();
        let signed_error = oracle.score - greedy.score;
        let oracle_blocks = has_block_action(&oracle.actions);
        let greedy_blocks = has_block_action(&greedy.actions);

        println!(
            "{}\t{:?}\t{:?}\t{:?}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{:.2}\t{:.2}\t{:.2}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{:.3}\t{:.3}\t{:?}\t{:?}",
            spec.name,
            spec.difficulty,
            spec.hand_strength,
            spec.phase,
            spec.enemies.len(),
            spec.hand.len(),
            spec.phase.decision_phase_count(),
            spec.blocking_relevant,
            spec.card_preservation_relevant,
            oracle_blocks,
            greedy_blocks,
            first_action_match,
            signed_error,
            oracle.score,
            greedy.score,
            oracle.fame_gained,
            greedy.fame_gained,
            oracle.wounds_taken,
            greedy.wounds_taken,
            oracle.cards_remaining,
            greedy.cards_remaining,
            oracle.complete,
            oracle.nodes_visited,
            greedy.nodes_visited,
            oracle_elapsed.as_secs_f64() * 1_000.0,
            greedy_elapsed.as_secs_f64() * 1_000.0,
            oracle.actions.first(),
            greedy.actions.first(),
        );

        records.push(DiagnosticRecord {
            spec,
            oracle,
            greedy,
            oracle_elapsed,
            greedy_elapsed,
            first_action_match,
            signed_error,
            oracle_blocks,
            greedy_blocks,
            oracle_remaining_hand: remaining_hand(&oracle_state),
            greedy_remaining_hand: remaining_hand(&greedy_state),
            oracle_combat_remaining: combat_remaining(&oracle_state),
            greedy_combat_remaining: combat_remaining(&greedy_state),
        });
    }

    println!(
        "SUMMARY\tcount={}\toracle_complete={}\tfirst_match_rate={:.3}\tmean_signed={:.2}\tmean_abs={:.2}\toracle_ms={:.2}\tgreedy_ms={:.2}\tspeed_ratio={:.1}",
        records.len(),
        records.iter().filter(|record| record.oracle.complete).count(),
        mean(records.iter().map(|record| f64::from(record.first_action_match))),
        mean(records.iter().map(|record| record.signed_error)),
        mean(records.iter().map(|record| record.signed_error.abs())),
        records.iter().map(|record| record.oracle_elapsed.as_secs_f64()).sum::<f64>() * 1_000.0,
        records.iter().map(|record| record.greedy_elapsed.as_secs_f64()).sum::<f64>() * 1_000.0,
        records.iter().map(|record| record.oracle_elapsed.as_secs_f64()).sum::<f64>()
            / records.iter().map(|record| record.greedy_elapsed.as_secs_f64()).sum::<f64>(),
    );
    print_boolean_group(&records, "blocking_tag", |record| {
        record.spec.blocking_relevant
    });
    print_boolean_group(&records, "oracle_blocks_greedy_skips", |record| {
        record.oracle_blocks && !record.greedy_blocks
    });
    print_boolean_group(&records, "preservation_tag", |record| {
        record.spec.card_preservation_relevant
    });
    print_category_group(&records, "difficulty", |record| {
        format!("{:?}", record.spec.difficulty)
    });
    print_category_group(&records, "hand_strength", |record| {
        format!("{:?}", record.spec.hand_strength)
    });
    print_category_group(&records, "phase", |record| {
        format!("{:?}", record.spec.phase)
    });
    print_numeric_group(&records, "enemy_count", |record| record.spec.enemies.len());
    print_numeric_group(&records, "hand_size", |record| record.spec.hand.len());
    print_numeric_group(&records, "decision_phases", |record| {
        record.spec.phase.decision_phase_count()
    });

    for record in records
        .iter()
        .filter(|record| record.oracle_blocks && !record.greedy_blocks)
    {
        println!(
            "SKIP\tfixture={}\ttags={:?}/{:?}/{:?}\tsigned_error={:.2}\toracle_outcome=fame:{} wounds:{} cards:{} crystals:{} units:{} ko:{}\tgreedy_outcome=fame:{} wounds:{} cards:{} crystals:{} units:{} ko:{}\toracle_path={:?}\tgreedy_path={:?}",
            record.spec.name,
            record.spec.difficulty,
            record.spec.hand_strength,
            record.spec.phase,
            record.signed_error,
            record.oracle.fame_gained,
            record.oracle.wounds_taken,
            record.oracle.cards_remaining,
            record.oracle.crystals_spent,
            record.oracle.units_newly_wounded,
            record.oracle.knocked_out,
            record.greedy.fame_gained,
            record.greedy.wounds_taken,
            record.greedy.cards_remaining,
            record.greedy.crystals_spent,
            record.greedy.units_newly_wounded,
            record.greedy.knocked_out,
            record.oracle.actions,
            record.greedy.actions,
        );
    }

    records.sort_by(|left, right| right.signed_error.abs().total_cmp(&left.signed_error.abs()));
    for (rank, record) in records.iter().take(5).enumerate() {
        println!(
            "WORST\trank={}\tfixture={}\ttags={:?}/{:?}/{:?}\tsigned_error={:.2}\toracle_first={:?}\tgreedy_first={:?}\toracle_outcome=fame:{} wounds:{} cards:{} crystals:{} units:{} ko:{} remaining_enemies:{} hand:{:?}\tgreedy_outcome=fame:{} wounds:{} cards:{} crystals:{} units:{} ko:{} remaining_enemies:{} hand:{:?}\toracle_path={:?}\tgreedy_path={:?}",
            rank + 1,
            record.spec.name,
            record.spec.difficulty,
            record.spec.hand_strength,
            record.spec.phase,
            record.signed_error,
            record.oracle.actions.first(),
            record.greedy.actions.first(),
            record.oracle.fame_gained,
            record.oracle.wounds_taken,
            record.oracle.cards_remaining,
            record.oracle.crystals_spent,
            record.oracle.units_newly_wounded,
            record.oracle.knocked_out,
            record.oracle_combat_remaining,
            record.oracle_remaining_hand,
            record.greedy.fame_gained,
            record.greedy.wounds_taken,
            record.greedy.cards_remaining,
            record.greedy.crystals_spent,
            record.greedy.units_newly_wounded,
            record.greedy.knocked_out,
            record.greedy_combat_remaining,
            record.greedy_remaining_hand,
            record.oracle.actions,
            record.greedy.actions,
        );
    }
}
